CREATE DATABASE IF NOT EXISTS inventory_supply_chain_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE inventory_supply_chain_db;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('Admin','Manager','Staff') NOT NULL DEFAULT 'Admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,description TEXT,status ENUM('Active','Inactive') DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,company VARCHAR(160),phone VARCHAR(30),email VARCHAR(190),address TEXT,status ENUM('Active','Inactive') DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,phone VARCHAR(30),email VARCHAR(190),address TEXT,status ENUM('Active','Inactive') DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS warehouses(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,location VARCHAR(255),manager VARCHAR(140),capacity INT DEFAULT 0,status ENUM('Active','Inactive') DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,sku VARCHAR(80) NOT NULL UNIQUE,category_id INT,supplier_id INT,warehouse_id INT,purchase_price DECIMAL(12,2) NOT NULL DEFAULT 0,selling_price DECIMAL(12,2) NOT NULL DEFAULT 0,quantity INT NOT NULL DEFAULT 0,minimum_stock INT NOT NULL DEFAULT 5,description TEXT,status ENUM('Active','Inactive') DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_product_name(name),CONSTRAINT fk_product_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,CONSTRAINT fk_product_supplier FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL,CONSTRAINT fk_product_warehouse FOREIGN KEY(warehouse_id) REFERENCES warehouses(id) ON DELETE SET NULL,CHECK(quantity>=0),CHECK(purchase_price>=0),CHECK(selling_price>=0));
CREATE TABLE IF NOT EXISTS purchases(id INT AUTO_INCREMENT PRIMARY KEY,supplier_id INT NOT NULL,product_id INT NOT NULL,warehouse_id INT NOT NULL,quantity INT NOT NULL,purchase_price DECIMAL(12,2) NOT NULL,total_amount DECIMAL(14,2) NOT NULL,payment_status ENUM('Paid','Pending','Partial') DEFAULT 'Paid',purchase_date DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_purchase_date(purchase_date),FOREIGN KEY(supplier_id) REFERENCES suppliers(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS sales(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,selling_price DECIMAL(12,2) NOT NULL,total_amount DECIMAL(14,2) NOT NULL,payment_status ENUM('Paid','Pending','Partial') DEFAULT 'Paid',sale_date DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_sale_date(sale_date),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(product_id) REFERENCES products(id),CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,total_amount DECIMAL(14,2) NOT NULL,payment_status ENUM('Paid','Pending','Partial') DEFAULT 'Pending',order_status ENUM('Pending','Processing','Shipped','Delivered','Cancelled') DEFAULT 'Pending',order_date DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS stock_movements(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,warehouse_id INT,movement_type ENUM('Purchase','Sale','Return','Adjustment','Transfer') NOT NULL,quantity INT NOT NULL,previous_stock INT NOT NULL,new_stock INT NOT NULL,reference VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_movement_date(created_at),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS settings(id INT PRIMARY KEY DEFAULT 1,company_name VARCHAR(160) DEFAULT 'Stockwise Trading',company_email VARCHAR(190),company_phone VARCHAR(30),company_address TEXT,currency VARCHAR(10) DEFAULT 'INR',date_format VARCHAR(30) DEFAULT 'DD/MM/YYYY',low_stock_alerts BOOLEAN DEFAULT TRUE,sales_notifications BOOLEAN DEFAULT TRUE,purchase_notifications BOOLEAN DEFAULT TRUE,theme VARCHAR(20) DEFAULT 'Light',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS notifications(id INT AUTO_INCREMENT PRIMARY KEY,type ENUM('Low Stock','Out of Stock','Sale','Purchase','Pending Order','Info') NOT NULL,message VARCHAR(500) NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_notifications_unread(is_read,created_at));
